/* haeckel-radiolaria — scroll is time: radiolaria plate: line first, then
   radiolaria ink in radially with subtle depth parallax. Final frame is the plate itself. */
export function haeckelRadiolaria(runway, opts = {}) {
  const frame = runway.querySelector('.hr-frame');
  const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
  let raf = 0, target = 0, current = reduced ? 1 : 0, visible = true, destroyed = false;
  const clamp01 = v => Math.min(1, Math.max(0, v));
  function measure() {
    const r = runway.getBoundingClientRect();
    const total = runway.offsetHeight - innerHeight;
    target = total > 0 ? clamp01(-r.top / total) : 1;
  }
  function apply() {
    frame.style.setProperty('--p', current.toFixed(4));
    frame.style.setProperty('--wet', (4 * current * (1 - current)).toFixed(4));
  }
  let vel = 0;
  function tick() {
    raf = 0;
    const w = target > current ? 10 : 15;
    const dt = 1 / 60;
    vel += (-w * w * (current - target) - 2 * w * vel) * dt;
    current = clamp01(current + vel * dt);
    if (Math.abs(target - current) < 0.0004 && Math.abs(vel) < 0.0004) { current = target; vel = 0; apply(); return; }
    apply();
    if (visible && !document.hidden && !destroyed) raf = requestAnimationFrame(tick);
  }
  function kick() { measure(); if (!raf && visible && !destroyed) raf = requestAnimationFrame(tick); }
  const onScroll = () => kick(), onResize = () => kick();
  addEventListener('scroll', onScroll, { passive: true });
  addEventListener('resize', onResize);
  const io = new IntersectionObserver(e => { visible = e[0].isIntersecting; if (visible) kick(); else if (raf) { cancelAnimationFrame(raf); raf = 0; } });
  io.observe(runway);
  if (reduced) { current = target = 1; apply(); }
  else kick();
  return function destroy() {
    destroyed = true;
    if (raf) cancelAnimationFrame(raf);
    removeEventListener('scroll', onScroll); removeEventListener('resize', onResize);
    io.disconnect();
    frame.style.removeProperty('--p'); frame.style.removeProperty('--wet');
  };
}
let api = null;
const el = document.querySelector('[data-haeckel-radiolaria]');
if (el) api = haeckelRadiolaria(el);
export function destroy() { if (api) { api(); api = null; } }
if (typeof window !== 'undefined') window.__haeckelRadiolaria = { destroy };

/* haeckel-radiolaria — forms ink in radially, faint depth parallax settles out. */
*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{background:#f2eee1;overflow-x:hidden}
.hr-runway{height:380vh;position:relative}
.hr-stage{position:sticky;top:0;height:100svh;display:grid;place-items:center;background:#f2eee1;overflow:hidden}
.hr-frame{position:relative;height:min(94svh,1180px);aspect-ratio:1920/2737;max-width:94vw;touch-action:pan-y}
.hr-frame img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;display:block;pointer-events:none;user-select:none;-webkit-user-drag:none}
.hr-base{filter:grayscale(1) contrast(1.13) brightness(1.07) sepia(.22);
  transform:scale(calc(1 + (1 - var(--p,0))*.035));transform-origin:50% 50%}
.hr-mid{filter:saturate(1.05);
  transform:scale(calc(1 + (1 - var(--p,0))*.018));transform-origin:50% 50%;
  -webkit-mask-image:radial-gradient(circle at 50% 46%,#000 calc(var(--p,0)*72%),transparent calc(var(--p,0)*72% + 10%));
  mask-image:radial-gradient(circle at 50% 46%,#000 calc(var(--p,0)*72%),transparent calc(var(--p,0)*72% + 10%))}
.hr-top{transform:scale(calc(1 + (1 - var(--p,0))*.006));transform-origin:50% 50%;
  -webkit-mask-image:radial-gradient(circle at 50% 46%,#000 calc(var(--p,0)*128%),transparent calc(var(--p,0)*128% + 9%));
  mask-image:radial-gradient(circle at 50% 46%,#000 calc(var(--p,0)*128%),transparent calc(var(--p,0)*128% + 9%))}
@media (prefers-reduced-motion: reduce){
  .hr-runway{height:auto}
  .hr-stage{position:static;height:auto;padding:4svh 0}
  .hr-base,.hr-mid,.hr-top{transform:none}
  .hr-mid,.hr-top{-webkit-mask-image:none;mask-image:none}
}

